"use strict";(self.webpackChunkdocusaurus_wiki=self.webpackChunkdocusaurus_wiki||[]).push([[4546],{3676:(e,r,t)=>{t.r(r),t.d(r,{assets:()=>o,contentTitle:()=>l,default:()=>c,frontMatter:()=>n,metadata:()=>s,toc:()=>m});var i=t(7462),u=(t(7294),t(3905)),a=(t(6256),t(3767));const n={title:"Fermi\xe8re"},l=void 0,s={unversionedId:"roles/fermiere",id:"roles/fermiere",title:"Fermi\xe8re",description:"Description",source:"@site/docs/roles/fermiere.mdx",sourceDirName:"roles",slug:"/roles/fermiere",permalink:"/botc-wiki/docs/roles/fermiere",draft:!1,tags:[],version:"current",frontMatter:{title:"Fermi\xe8re"}},o={},m=[{value:"Description",id:"description",level:3},{value:"Exemples",id:"exemples",level:3},{value:"M\xe9caniques et conseils",id:"m\xe9caniques-et-conseils",level:3},{value:"Bluffer la Fermi\xe8re",id:"bluffer-la-fermi\xe8re",level:3},{value:"Comment conter",id:"comment-conter",level:3}],p={toc:m};function c(e){let{components:r,...t}=e;return(0,u.kt)("wrapper",(0,i.Z)({},p,t,{components:r,mdxType:"MDXLayout"}),(0,u.kt)(a.Z,{FERMIERE:!0,header:!0,mdxType:"Role"}),(0,u.kt)("h3",{id:"description"},"Description"),(0,u.kt)("p",null,"Lorsque vous mourez la nuit, un autre joueur Gentil vivant devient une Fermi\xe8re."),(0,u.kt)("p",null,"La Fermi\xe8re cr\xe9\xe9 d\u2019autres Fermi\xe8res."),(0,u.kt)("ul",null,(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Si une Fermi\xe8re meurt la nuit, un autre joueur devient une Fermi\xe8re aussi.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Seuls les joueurs gentils peuvent devenir Fermi\xe8re de cette fa\xe7on.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Si cette nouvelle Fermi\xe8re meurt aussi la nuit, un autre Fermi\xe8re est cr\xe9\xe9e.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Les Fermi\xe8res qui meurent le jour, par exemple, par ex\xe9cution, ne cr\xe9ent pas de nouvelles Fermi\xe8res.  ")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Les Fermi\xe8res qui sont pass\xe9s Mal\xe9fiques, par exemple, \xe0 cause du Mezepheles, peuvent cr\xe9er d\u2019autres Fermi\xe8res. Mais les Villageois et les Marginaux qui sont devenus Mal\xe9fiques ne peuvent pas devenir Fermi\xe8res.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Les Fermi\xe8res ne se reconnaissent pas mais chaque joueur qui est devenu Fermi\xe8re apprend qu\u2019il est maintenant Fermi\xe8re.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Quand un joueur devient Fermi\xe8re, il n\u2019a plus son ancien r\xf4le avec la capacit\xe9 associ\xe9e. Tous les effets caus\xe9s par leur ancienne capacit\xe9 se termine imm\xe9diatement."))),(0,u.kt)("h3",{id:"exemples"},"Exemples"),(0,u.kt)("blockquote",null,(0,u.kt)("p",{parentName:"blockquote"},"Samuel est la Fermi\xe8re. Le D\xe9mon le tue la nuit. Claire est le ",(0,u.kt)(a.Z,{TOURMENTEUR:!0,mdxType:"Role"})," et Lucas est l\u2019",(0,u.kt)(a.Z,{ALCHIMISTE:!0,mdxType:"Role"}),". Lucas devient une Fermi\xe8re cette nuit. Claire ne pouvait devenir Fermi\xe8re car elle est Mal\xe9fique.")),(0,u.kt)("blockquote",null,(0,u.kt)("p",{parentName:"blockquote"},"La deuxi\xe8me nuit, la Fermi\xe8re meurt. Le ",(0,u.kt)(a.Z,{CHORISTE:!0,mdxType:"Role"})," devient la Fermi\xe8re. La troisi\xe8me nuit, la nouvelle Fermi\xe8re meurt \xe0 son tour alors l\u2019",(0,u.kt)(a.Z,{HERETIQUE:!0,mdxType:"Role"})," devient Fermi\xe8re. Il n\u2019y a maintenant plus d\u2019",(0,u.kt)(a.Z,{HERETIQUE:!0,mdxType:"Role"})," et d\u2019",(0,u.kt)(a.Z,{CHORISTE:!0,mdxType:"Role"})," en jeu mais trois Fermi\xe8res dont deux sont mortes.")),(0,u.kt)("h3",{id:"m\xe9caniques-et-conseils"},"M\xe9caniques et conseils"),(0,u.kt)("ul",null,(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Si vous mourez la nuit, restez tranquille et attendez que quelqu\u2019un vienne vous voir en pr\xe9tendant \xeatre devenu Fermi\xe8re.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"La Fermi\xe8re peut \xeatre un pi\xe8ge puissant contre les Mal\xe9fiques. Si vous devenez Fermi\xe8re cette nuit, allez parler au joueur qui vient de mourir et dites-lui que vous \xeates maintenant Fermi\xe8re. Il est tr\xe8s difficile de fausser cette interaction ce qui signifie que vous pouvez vous faire mutuellement confiance.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Si vous pr\xe9f\xe9rez survire, vous pouvez vous d\xe9voiler comme Fermi\xe8re et provoquer le D\xe9mon pour qu\u2019il vous tue la nuit. C\u2019est particuli\xe8rement efficace s\u2019il n\u2019y a pas d\u2019autres causes de morts la nuit dans le script. \xc7a peut aussi laisser le doute au D\xe9mon qui peut douter de vos intentions.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Pr\xe9tendez \xeatre une cible de haute priorit\xe9 comme le ",(0,u.kt)(a.Z,{CHASSEUR_DE_PRIMES:!0,mdxType:"Role"})," ou la ",(0,u.kt)(a.Z,{VOYANTE:!0,mdxType:"Role"})," pour inciter le D\xe9mon \xe0 vous attaquer la nuit. Une fois que vous \xeates mort et que vous avez confirm\xe9 l\u2019identit\xe9 de la nouvelle Fermi\xe8re, pr\xe9tendez avoir \xe9chang\xe9 de r\xf4le avec ce joueur et que c\u2019est en r\xe9alit\xe9 lui qui a le r\xf4le qui est une cible de haute priorit\xe9 pour inciter le D\xe9mon \xe0 le tuer aussi.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Essayez de ne pas vous d\xe9voiler publiquement tout de suite car avoir un grand groupe de Fermi\xe8re est bien plus puissant qu\u2019avoir un petit groupe de Fermi\xe8re. Analyser les informations que la nouvelle Fermi\xe8re pouvait avoir car vous pouvez lui faire confiance.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Essayez de trouver une cible de haute priorit\xe9 pour \xe9changer de r\xf4le avec elle pour que vous attiriez l\u2019attention pour \xeatre tu\xe9 la nuit mais aussi pour prot\xe9ger ce joueur, en particulier si vous \xeates la Fermi\xe8re originelle. ")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Essayez de parler avec beaucoup de joueurs dans la partie afin de faire croire que vous faites passer beaucoup d\u2019informations puissantes contre les Mal\xe9fiques et de passer pour une cible de haute priorit\xe9 pour le D\xe9mon qui doit \xeatre r\xe9duite au silence.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Evitez l\u2019ex\xe9cution a tout prix car votre capacit\xe9 ne se d\xe9clenche que si vous mourez la nuit.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Apr\xe8s avoir confirm\xe9 quelques joueurs qui sont devenus Fermi\xe8res, d\xe9voilez-vous ensemble et utilisez cette information comme base pour chercher les Mal\xe9fiques. Cela peut \xeatre une tr\xe8s bonne strat\xe9gie pour savoir \xe0 qui faire ou ne pas faire confiance. ")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"S\u2019il y a une chaine de Fermi\xe8re qui est sup\xe9rieure au nombre de Mal\xe9fiques en jeu, cela signiie que vous pouvez faire confiance \xe0 tous les Fermi\xe8res du groupe.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Transformer un puissant r\xf4le \xe0 informations en Fermi\xe8re est bien plus b\xe9n\xe9fique que d\u2019essayer de garder cette personne en vie la nuit. N\u2019ayez pas peur de mourir la nuit par crainte de transformer ce r\xf4le en Fermi\xe8re.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Pr\xeatez attention \xe0 au r\xf4le qu\u2019\xe9tait le joueur avant de devenir Fermi\xe8re. Si c\u2019\xe9tait un Marginal, \xe7a peut \xeatre un indice que le village est mal en point et que le Conteur essaye d\u2019aider. Si c\u2019est un joueur \xe0 information de premi\xe8re nuit ou un r\xf4le \xe0 usage unique, \xe7a peut signifier que la partie est \xe9quilibr\xe9e. Si c\u2019est un r\xf4le puissant alors qu\u2019il y aurait eu d\u2019autres choix, peut \xeatre que cela signifie que le village est en tr\xe8s bonne voie. "))),(0,u.kt)("h3",{id:"bluffer-la-fermi\xe8re"},"Bluffer la Fermi\xe8re"),(0,u.kt)("ul",null,(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Un bluff Fermi\xe8re peut \xeatre un bon bluff de secours en fin de partie. Si vous avez essay\xe9 de garder des choses secr\xe8tes. La Fermi\xe8re ne va probablement pas se d\xe9voiler t\xf4t et \xe7a peut vous donner une couverture si vous aviez bluff\xe9 un r\xf4le et que \xe7a ne tient plus.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Dites seulement \xe0 1 ou 2 joueurs que vous \xeates la Fermi\xe8re et garder ces personnes en vie jusqu\u2019\xe0 la fin de partie pour les faire passer pour D\xe9mon ou mal\xe9fique pour justifier pourquoi vous n\u2019est pas mort la nuit est un bluff puissant.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Si un mal\xe9fique meurt la nuit pour n\u2019importe quelle raison, vous pouvez commencer un bluff de Fermi\xe8re. Allez simplement le voir et dites-lui secr\xe8tement que vous \xeates \xab devenu Fermi\xe8re \xbb cette nuit apr\xe8s sa mort. \xc7a peut \xeatre particuli\xe8rement puissant avec un D\xe9mon qui aime tuer ses Sbires come le ",(0,u.kt)(a.Z,{VIGORMORTIS:!0,mdxType:"Role"}),".")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Bluffer Fermi\xe8re peut \xeatre difficile car vous aurez besoin de travailler conjointement avec d\u2019autres Mal\xe9fiques pour que \xe7a fonctionne. Si, pour une raison, l\u2019un de vous meurt la nuit, vous pouvez pr\xe9tendre que vous \xe9tiez Fermi\xe8re. Cela cr\xe9\xe9 une ouverture pour qu\u2019un autre mal\xe9fique pr\xe9tendre \xeatre maintenant la Fermi\xe8re et donc v\xe9rifier votre d\xe9claration. Toutefois, \xe7a ne veut pas dire que les autres vous feront confiance car \xe7a ne fait que confirmez que vous \xeates ensembles.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Bluffer Fermi\xe8re peut \xeatre une bonne fa\xe7on de neutraliser une v\xe9ritable Fermi\xe8re. Si vous vous d\xe9voilez comme Fermi\xe8re, la v\xe9ritable Fermi\xe8re pourrait se sentir forc\xe9e de mettre en \xe9vidence le doublon de r\xf4le pour emp\xeacher les joueurs de croire en votre histoire."))),(0,u.kt)("h3",{id:"comment-conter"},"Comment conter"),(0,u.kt)("p",null,"Si une Fermi\xe8re meurt cette nuit, r\xe9veillez un joueur gentil vivant. Montrez-lui le jeton d\u2019information \xab\xa0TU ES\xa0\xbb et un jeton de r\xf4le de Fermi\xe8re puis rendormez-le. Remplacez son jeton de r\xf4le pr\xe9c\xe9dent pas un jeton de r\xf4le de Fermi\xe8re."),(0,u.kt)("p",null,(0,u.kt)("strong",{parentName:"p"}," Compl\xe9ments Conteur")),(0,u.kt)("p",null,"Les changements en Fermi\xe8re se produisent \xe0 l\u2019instant o\xf9 la Fermi\xe8re meurt. Donc si un D\xe9mon qui attaque qui plusieurs fois ou qu\u2019il y a une Comm\xe8re, un Assassin ou un Parrain ou quelque chose comme \xe7a, il pourrait y avoir plusieurs transformations de Fermi\xe8res dans la m\xeame nuit car une premi\xe8re attaque peut tuer la Fermi\xe8re et cr\xe9er un nouveau Fermi\xe8re qui peut \xeatre tu\xe9 plus tard dans la nuit, etc... Si la Fermi\xe8re est ivre ou empoisonn\xe9 \xe0 sa mort, rien ne se passe. Si la Fermi\xe8re meut durant la journ\xe9e, peu importe comment, rien ne se passe."),(0,u.kt)("p",null,(0,u.kt)("strong",{parentName:"p"},"Interaction notables")),(0,u.kt)("ul",null,(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{CANNIBALE:!0,mdxType:"Role"})," / ",(0,u.kt)(a.Z,{PHILOSOPHE:!0,mdxType:"Role"})," / ",(0,u.kt)(a.Z,{PIXIE:!0,mdxType:"Role"})," : Si un joueur qui a gagn\xe9 la capacit\xe9 de Fermi\xe8re meurt cette nuit, il transforme un joueur gentil vivant en Fermi\xe8re peu importe son v\xe9ritable r\xf4le."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{FEMME_DE_CHAMBRE:!0,mdxType:"Role"})," : Si une Femme de chambre choisi un joueur qui a commenc\xe9 la nuit en \xe9tant un autre r\xf4le (qui ne se r\xe9veille pas ou qui se r\xe9veille apr\xe8s la transformation) et qu\u2019il est devenu Fermi\xe8re durant la nuit (et qu\u2019il s\u2019est donc r\xe9veill\xe9 pour l\u2019apprendre), il ne se r\xe9veille pas d\xfb \xe0 sa propre capacit\xe9. Il se r\xe9veille car son r\xf4le a chang\xe9 et qu\u2019il doit en \xeatre inform\xe9. Toutefois, s\u2019il s\u2019est r\xe9veill\xe9 plus t\xf4t \xe0 cause de sa capacit\xe9 avant de devenir Fermi\xe8re, \xe7a comptera comme un 1 pour la Femme de chambre m\xeame s\u2019il a une autre capacit\xe9 maintenant.)"),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{PARIEUR:!0,mdxType:"Role"})," : Si un Parieur a mal pari\xe9 et est d\xe9j\xe0 mort, il ne peut pas devenir la Fermi\xe8re plus tard dans la nuit car il est d\xe9j\xe0 mort."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{COMMERE:!0,mdxType:"Role"})," : Si la Comm\xe8re devient une Fermi\xe8re avant que son comm\xe9rage ne tue, un potentiel comm\xe9rage vrai ne tuera pas car la Comm\xe8re est devenue Fermi\xe8re avant que la mort ne se produise. Toutefois, une Comm\xe8re peut tuer une Fermi\xe8re ce qui d\xe9clenchera sa capacit\xe9. La Comm\xe8re qui a tu\xe9 la Fermi\xe8re peut m\xeame devenir Fermi\xe8re elle-m\xeame."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{MAMIE:!0,mdxType:"Role"})," : Si une Fermi\xe8re est la descendance et est tu\xe9e, c\u2019est au choix du Conteur. La Mamie peut devenir la Fermi\xe8re et ne pas mourir (car c\u2019est maintenant une Fermi\xe8re et donc la capacit\xe9 de Mamie qui la fait mourir n\u2019est plus en jeu) ou la Mamie meurt de sa capacit\xe9 et donc ne peut pas devenir Fermi\xe8re\u2026 On peut tout simplement \xe9viter cette question en n\u2019essayant pas de transformer la Mamie en Fermi\xe8re."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{LEVIATHAN:!0,mdxType:"Role"})," : Jinx\xe9 : Si le L\xe9viathan est jeu et qu\u2019une Fermi\xe8re meurt par ex\xe9cution, un joueur gentil devient une Fermi\xe8re cette nuit."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{LYCANTHROPE:!0,mdxType:"Role"})," : Si le Lycanthrope tue la Fermi\xe8re puis qu\u2019il devient la Fermi\xe8re, d\u2019autres morts peuvent se produire cette nuit-l\xe0 car il n\u2019y a plus de capacit\xe9 de Lycanthrope en jeu qui emp\xeache la mort."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{MATHEMATICIEN:!0,mdxType:"Role"})," : N\u2019aura pas un +1 d\u2019un joueur devenant Fermi\xe8re et qui ne peut plus utiliser sa capacit\xe9 pr\xe9c\xe9dente. Aux yeux du Math\xe9maticien, ce joueur est Fermi\xe8re et sa capacit\xe9 fonctionne bien."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{MAIRE:!0,mdxType:"Role"})," : Peut faire rebondir l\u2019attaque du D\xe9mon sur la Fermi\xe8re. Il peut aussi devenir lui-m\xeame la Fermi\xe8re apr\xe8s le rebond."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{PLANTEUR_DE_PAVOT:!0,mdxType:"Role"})," : Si le Planteur de pivot devient la Fermi\xe8re, les Mal\xe9fiques ne se reconnaitront pas."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{BRUTE:!0,mdxType:"Role"})," : Peut devenir la Fermi\xe8re (si Gentille). Le pr\xe9c\xe9dent Fermi\xe8re ne choisit pas la Brute lui-m\xeame avec sa capacit\xe9. C\u2019est le Conteur. Donc la Brute ne provoquera l\u2019ivresse du Fermi\xe8re."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{ESPIONNE:!0,mdxType:"Role"})," : Peut \xeatre consid\xe9r\xe9 comme Gentil pour la Fermi\xe8re."),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{EMEUTIER:!0,mdxType:"Role"})," : Jinx : \xab Chaque nuit*, l'Emeutier choisit un joueur vivant (diff\xe9rent des nuits pr\xe9c\xe9dentes) : Une Fermi\xe8re choisie utilise sa capacit\xe9 mais ne meurt pas. \xbb"),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{LEVIATHAN:!0,mdxType:"Role"})," : Jinx : \xab Chaque nuit*, le L\xe9viathan choisit un joueur vivant (diff\xe9rent des nuits pr\xe9c\xe9dentes) : Une Fermi\xe8re choisie meurt et obtient sa capacit\xe9. \xbb"),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)("p",{parentName:"li"},"Voyageurs : Avec les r\xe8gles standard de BOTC, les Voyageurs ne peuvent pas changer de r\xf4le et donc un Voyageur vivant gentil ne peut pas devenir Fermi\xe8re. Si vous ou votre Conteur joue avec une variante ou c\u2019est l\xe9gitime, quand un Voyageur devient la Fermi\xe8re, vous changerez son jeton de vie sur la place du village par un jeton standard plut\xf4t qu\u2019un jeton de Voyageur.")),(0,u.kt)("li",{parentName:"ul"},(0,u.kt)(a.Z,{BARISTA:!0,mdxType:"Role"})," : Si le Barista le fait agir deux fois, la mort du Fermi\xe8re causera la transformation de deux joueurs gentils en Fermi\xe8res.")))}c.isMDXComponent=!0}}]);